-- The curriculum of each course lives in public.lectures: one row per session, with the lessons it covers and,
-- once uploaded, the recording. Staff edit it in the control panel; students see every session of their courses,
-- with the recording fields only when the session is published and released. Run after 0007.
-- The inserts below seed the sessions from content/courses/*.json; existing rows at the same position are kept
-- and only given their lessons.

alter table public.lectures add column if not exists lessons jsonb not null default '[]'::jsonb;

-- Students see the whole curriculum of their courses; video fields appear only when published and released.
drop policy if exists "students see released lectures of their courses" on public.lectures;
create policy "students see the curriculum of their courses" on public.lectures for select
  using (public.has_course_access(course_slug));

create or replace view public.lectures_student with (security_invoker = true) as
select id, course_slug, position, title, description, lessons, duration_min, published, release_at, created_at, updated_at,
       (published and (release_at is null or release_at <= now()) and (video_url is not null or video_path is not null)) as available,
       case when published and (release_at is null or release_at <= now()) then video_url end as video_url,
       case when published and (release_at is null or release_at <= now()) then video_path end as video_path
from public.lectures;

-- Staff may reorder freely; positions are swapped in two updates, so no unique constraint on (course_slug, position).

